SELECT d.nom, COUNT(e.idemp) AS nb_employes, ROUND(AVG(e.salaire)) AS salaire_moyen
FROM departement d LEFT JOIN employe e ON e.iddept = d.iddept
GROUP BY d.nom;

SELECT d.*
FROM departement d
WHERE NOT EXISTS (SELECT 1 FROM employe e WHERE e.iddept = d.iddept);

UPDATE employe
SET salaire = salaire * 1.05
WHERE dateembauche < ADD_MONTHS(SYSDATE, -120);
COMMIT;
- Dix ans = 120 mois.

SET SERVEROUTPUT ON
DECLARE
  CURSOR c (p_dept NUMBER) IS
    SELECT nom, prenom, salaire FROM employe WHERE iddept = p_dept ORDER BY salaire DESC;
  v_nom    employe.nom%TYPE;
  v_prenom employe.prenom%TYPE;
  v_sal    employe.salaire%TYPE;
BEGIN
  OPEN c(&p_dept);
  LOOP
    FETCH c INTO v_nom, v_prenom, v_sal;
    EXIT WHEN c%NOTFOUND;
    DBMS_OUTPUT.PUT_LINE(v_nom || ' ' || v_prenom || ' : ' || v_sal);
  END LOOP;
  CLOSE c;
END;
/
- Curseur paramétré ; EXIT WHEN c%NOTFOUND juste après FETCH ; CLOSE à la fin.

CREATE OR REPLACE FUNCTION chargeemploye (p_id IN NUMBER) RETURN NUMBER IS
  v_total NUMBER;
BEGIN
  SELECT NVL(SUM(heures), 0) INTO v_total FROM affectation WHERE idemp = p_id;
  RETURN v_total;
END;
/
SELECT idemp, nom, chargeemploye(idemp) FROM employe;
